export function normalizeHeaders(e){return e?e instanceof Headers?Object.fromEntries(e.entries()):Array.isArray(e)?Object.fromEntries(e):{...e}:{}}export function createFetchWithInit(e=fetch,r){return r?async(t,n)=>{const a={...r,...n,headers:n?.headers?{...normalizeHeaders(r.headers),...normalizeHeaders(n.headers)}:r.headers};return e(t,a)}:e}